// Accept payloads from BOTH:
//  A) GHL Workflow Webhook Action — Custom Data llega en body.customData.*
//  B) Dashboard fetch directo — todo en body.*
let rawBody = $input.item.json.body || $input.item.json;
if (typeof rawBody === 'string') { try { rawBody = JSON.parse(rawBody); } catch(e) { rawBody = {}; } }
rawBody = rawBody || {};

// Mergear customData (GHL Workflow Action) en el body raíz
const customData = (rawBody.customData && typeof rawBody.customData === 'object') ? rawBody.customData : {};
const body = Object.assign({}, customData, rawBody);

const contact_id = body.contact_id || body.contactId || (body.contact && body.contact.id) || null;
const tag = body.tag || null;
const opp_id = body.opportunity_id || body.opportunityId || null;

const source = body.source || (body.pago_id ? 'dashboard' : (body.tag ? 'ghl_tag' : 'unknown'));
const pago_id = body.pago_id || null;
const monto = body.monto != null ? parseFloat(body.monto) : null;
const metodo = body.metodo || null;
const booking_code = body.booking_code || null;
const notas = body.notas || null;
const trigger_type = body.trigger_type || (source === 'dashboard' ? 'dashboard_payment' : (tag ? 'tag_added' : 'unknown'));

if (!contact_id) {
  return { json: { valid: false, error: 'contact_id missing' } };
}

return { json: {
  valid: true,
  contact_id,
  trigger_type,
  tag,
  opp_id,
  source,
  pago_id,
  monto,
  metodo,
  booking_code,
  notas,
  is_dashboard: source === 'dashboard' && monto && monto > 0,
  is_ghl_tag: source === 'ghl_tag' || (tag === 'pago' && !pago_id),
  received_at: new Date().toISOString()
} };

// Detect anti-loop scenario: GHL tag fired AND there's a recent dashboard payment
const norm = $('Normalize').item.json;
const recent = $input.item.json;
const hasRecentPago = recent && recent.id;

// If it's a ghl_tag and there's a recent dashboard pago → LOOP (skip processing)
// Dashboard already did everything (invoice + CAPI), no need to duplicate
const is_loop = norm.is_ghl_tag && hasRecentPago;

return { json: {
  ...norm,
  recent_pago_id: hasRecentPago ? recent.id : null,
  is_loop
} };

// Build invoice line items from GHL custom field servicios + monto from dashboard
const norm = $('Normalize').item.json;
const contactResp = $('Get Contact GHL').item.json;
const contact = contactResp.contact || contactResp;
const cfs = contact.customFields || [];
const cfMap = {};
cfs.forEach(cf => { cfMap[cf.id] = cf.value; });

const servicios_raw = cfMap['ETSBOfoZqy1ng2RFBPzm'] || '';
const monto = norm.monto;
const metodo = norm.metodo || 'otro';

let names = [];
if (typeof servicios_raw === 'string' && servicios_raw.trim()) {
  names = servicios_raw.split(',').map(s => s.trim()).filter(Boolean);
}
if (names.length === 0) names = ['Servicio Exentia'];

const pricePerItem = Math.round((monto / names.length) * 100) / 100;
const items = names.map(function(name, i){
  const amount = i === names.length - 1
    ? Math.round((monto - pricePerItem * (names.length - 1)) * 100) / 100
    : pricePerItem;
  return { name, qty: 1, currency: 'MXN', amount };
});

const metodoMap = { tarjeta:'card', transferencia:'bank-transfer', efectivo:'cash', otro:'other' };
const ghl_method = metodoMap[metodo] || 'other';

const code = norm.booking_code || 'walkin-' + Date.now();

return { json: {
  contact_id: norm.contact_id,
  pago_id: norm.pago_id,
  monto,
  metodo,
  ghl_method,
  notas: norm.notas,
  items,
  invoice_number: 'EXE-' + code,
  invoice_name: 'Cita Exentia - ' + code,
  booking_code: norm.booking_code
} };

