// Extract custom fields from GHL contact and build Meta CAPI Purchase payload
function sha256(v) {
  if (!v) return null;
  const str = v.trim().toLowerCase();
  function rightRotate(val, amt) { return (val >>> amt) | (val << (32 - amt)); }
  const k = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let h0=0x6a09e667,h1=0xbb67ae85,h2=0x3c6ef372,h3=0xa54ff53a,h4=0x510e527f,h5=0x9b05688c,h6=0x1f83d9ab,h7=0x5be0cd19;
  const bytes = [];
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c < 128) bytes.push(c);
    else if (c < 2048) { bytes.push(192|(c>>6)); bytes.push(128|(c&63)); }
    else { bytes.push(224|(c>>12)); bytes.push(128|((c>>6)&63)); bytes.push(128|(c&63)); }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  bytes.push(0,0,0,0);
  bytes.push((bitLen>>>24)&0xff,(bitLen>>>16)&0xff,(bitLen>>>8)&0xff,bitLen&0xff);
  for (let offset = 0; offset < bytes.length; offset += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (bytes[offset+i*4]<<24)|(bytes[offset+i*4+1]<<16)|(bytes[offset+i*4+2]<<8)|bytes[offset+i*4+3];
    for (let i = 16; i < 64; i++) {
      const s0 = rightRotate(w[i-15],7)^rightRotate(w[i-15],18)^(w[i-15]>>>3);
      const s1 = rightRotate(w[i-2],17)^rightRotate(w[i-2],19)^(w[i-2]>>>10);
      w[i] = (w[i-16]+s0+w[i-7]+s1)|0;
    }
    let a=h0,b=h1,c=h2,d=h3,e=h4,f=h5,g=h6,h=h7;
    for (let i = 0; i < 64; i++) {
      const S1 = rightRotate(e,6)^rightRotate(e,11)^rightRotate(e,25);
      const ch = (e&f)^(~e&g);
      const t1 = (h+S1+ch+k[i]+w[i])|0;
      const S0 = rightRotate(a,2)^rightRotate(a,13)^rightRotate(a,22);
      const maj = (a&b)^(a&c)^(b&c);
      const t2 = (S0+maj)|0;
      h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;
    }
    h0=(h0+a)|0;h1=(h1+b)|0;h2=(h2+c)|0;h3=(h3+d)|0;h4=(h4+e)|0;h5=(h5+f)|0;h6=(h6+g)|0;h7=(h7+h)|0;
  }
  return [h0,h1,h2,h3,h4,h5,h6,h7].map(v=>(v>>>0).toString(16).padStart(8,'0')).join('');
}

const contactResp = $('Get Contact GHL').item.json;
const contact = contactResp.contact || contactResp;
const cfs = contact.customFields || [];
const cfMap = {};
cfs.forEach(cf => { cfMap[cf.id] = cf.value; });

const fbclid     = cfMap['vx52ah4vkjC7OENE0lWU'] || null;
const gclid      = cfMap['xgBoQXRSmURvYvhaxEzN'] || null;
const lead_ref   = cfMap['JgsK2j4h1p6Gf7pw0WDS'] || null;
const utm_source  = cfMap['37CfTVmnM6SUFq6XUnHh'] || null;
const utm_medium  = cfMap['NZPrbivrqIQFQx40cSsD'] || null;
const utm_campaign = cfMap['Kc5n7iZqisG3PBKhufQd'] || null;
const valor_raw  = cfMap['E3eEAnNb1rXfbh0Up3EE'];
const valor_cf   = valor_raw ? parseFloat(String(valor_raw).replace(/[^0-9.]/g,'')) : 0;
const servicios  = cfMap['ETSBOfoZqy1ng2RFBPzm'] || '';

const norm = $('Normalize').item.json;
const contact_id = norm.contact_id;
const valor = norm.is_dashboard && norm.monto ? norm.monto : valor_cf;

const email = contact.email || null;
const phone = contact.phone || null;
const firstName = contact.firstName || '';
const lastName = contact.lastName || '';

const event_id = 'ex_purchase_' + contact_id + '_' + (norm.pago_id || Date.now());
const event_time = Math.floor(Date.now() / 1000);

const user_data = {};
if (email) user_data.em = [sha256(email)];
if (phone) {
  let ph = phone.replace(/\D/g, '');
  if (!ph.startsWith('52') && ph.length === 10) ph = '52' + ph;
  user_data.ph = [sha256(ph)];
}
if (firstName) user_data.fn = [sha256(firstName)];
if (lastName) user_data.ln = [sha256(lastName)];
if (fbclid) user_data.fbc = 'fb.1.' + Date.now() + '.' + fbclid;
user_data.country = [sha256('mx')];

const capi_payload = {
  data: [{
    event_name: 'Purchase',
    event_time,
    event_id,
    action_source: 'system_generated',
    user_data,
    custom_data: {
      currency: 'MXN',
      value: valor || 0,
      content_name: servicios || 'Servicio Exentia',
      content_category: 'spa_service'
    }
  }],
  access_token: 'META_CAPI_TOKEN_REPLACE_AT_IMPORT'
};

const google_payload = gclid ? {
  conversions: [{
    gclid,
    conversion_action: 'PENDIENTE_CONVERSION_ACTION',
    conversion_date_time: new Date().toISOString().replace('T',' ').slice(0,19) + '-05:00',
    conversion_value: valor || 0,
    currency_code: 'MXN'
  }]
} : null;

const atribucion = {
  fbclid, gclid, lead_ref,
  utm_source, utm_medium, utm_campaign
};

return { json: {
  contact_id,
  email,
  phone,
  firstName,
  lastName,
  valor_ticket_mxn: valor,
  servicios,
  fbclid,
  gclid,
  lead_ref,
  atribucion,
  event_id,
  event_time,
  has_fbclid: !!fbclid,
  has_gclid: !!gclid,
  capi_payload,
  google_payload,
  capi_url: 'https://graph.facebook.com/v21.0/1405416301317321/events',
  source: norm.source,
  invoice_id: null
} };

const extract = $('Extract & Build CAPI').item.json;
const norm = $('Normalize').item.json;

return { json: {
  ok: true,
  contact_id: extract.contact_id,
  event_id: extract.event_id,
  valor_ticket_mxn: extract.valor_ticket_mxn,
  fbclid_present: extract.has_fbclid,
  gclid_present: extract.has_gclid,
  trigger_type: norm.trigger_type,
  source: norm.source
} };
